                    $members = [];
                    foreach (preg_split('/\r?\n/', $bytes) ?: [] as $line) {
                        $line = trim($line);
                        if ($line !== '') {
                            $members[$line] = $line;
                        }
                    }
            
                    return array_values($members);
                }
            
