                    ksort($source, SORT_NUMERIC);
                    $bytes = '';
                    $maxPage = max(array_keys($source));
                    for ($pageNumber = 1; $pageNumber <= $maxPage; $pageNumber++) {
                        $bytes .= $source[$pageNumber]['image'] ?? str_repeat("\0", $pageSize);
                    }
            
                    return $bytes;
                }
            
